/// <summary>
/// CB731_LaserNetBundleTOMultithreadBatch.
/// This is a service class for order shipment bundling report.
/// </summary>
class METOrderShipmentBundlingReportingJobService extends METSysOperationService
{
    private METOrderShipmentBundlingReportingJobContract contract;
    private SRSPrintDestinationSettings printDestinationSettings;
    private guid topPickingProcessId;

}

Method.Source:
// <summary>
/// Returns task service class name .
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METOrderShipmentBundlingReportingJobTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METOrderShipmentBundlingReportingJobTaskService, process);
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METOrderShipmentBundlingReportingJobContract _contract, SRSPrintDestinationSettings sRSPrintDestinationSettings)
{
    printDestinationSettings = sRSPrintDestinationSettings;

    this.processInternal(_contract);
}

/// <summary>
/// Initialise global variables.
/// </summary>
public void initialise()
{
    super();

    this.stageDataIntoQueue();
}

/// <summary>
/// Stages data into queue.
/// </summary>
void stageDataIntoQueue()
{
    #OCCRetryCount

    contract            = dataContract as METOrderShipmentBundlingReportingJobContract;
    topPickingProcessId = newGuid();

    try
    {
        ttsbegin;

        METOrderShipmentBundlingReportingJobQueue::cleanUpOrderShipmentBundlingReportQueue();
        this.stageOrderShipmentBundlingReportingJobRecords();

        ttscommit;

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        // catch the errors so processing can continue
        curext(); // avoids a warning about an empty block
    }
}

/// <summary>
/// Stages <c>METOrderShipmentBundlingReportingJobQueue</c> records.
/// </summary>
private void stageOrderShipmentBundlingReportingJobRecords()
{
    METOrderShipmentBundlingReportingJobQueue queue;
    METSalesOrderShipmentLoadHeader shipmentLoadHeader;
    QueryRun queryRun;
    RecordInsertList queueInsertList;
    boolean isFirstReport = true;

    queryRun = new QueryRun(contract.getQuery());
    queueInsertList = new RecordInsertList(tableNum(METOrderShipmentBundlingReportingJobQueue));

    while (queryRun.next())
    {
        shipmentLoadHeader = queryRun.get(tableNum(METSalesOrderShipmentLoadHeader));

        queue.clear();
        queue.ProcessId = topPickingProcessId;
        queue.SalesOrderShipmentLoadHeaderRecId = shipmentLoadHeader.RecId;

        if (isFirstReport)
        {
            queue.IsDangerousGoods = NoYes::Yes;
            isFirstReport = false;
        }

        queueInsertList.add(queue);
    }

    queueInsertList.insertDatabase();
}

/// <summary>
/// Initializes the task data contract.
/// </summary>
// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    contract = _taskDataContract as METOrderShipmentBundlingReportingJobContract;

    contract.parmTopPickingProcessId(topPickingProcessId);
    contract.parmPrintDestSettingsSerialized(FormJsonSerializer::serializeClass(printDestinationSettings));
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METOrderShipmentBundlingReportingJobContract();
}
